<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';$user=require_role('charity');$pdo=db();$charityId=(int)$user['charity_id'];
if(is_post()){verify_csrf();$appointmentId=(int)($_POST['appointment_id']??0);$stmt=$pdo->prepare("SELECT a.id,dp.id pledge_id FROM appointments a JOIN donation_pledges dp ON dp.id=a.pledge_id JOIN clothing_requests cr ON cr.id=dp.request_id WHERE a.id=? AND cr.charity_id=? AND a.status='booked'");$stmt->execute([$appointmentId,$charityId]);$appt=$stmt->fetch();if($appt){$pdo->beginTransaction();$pdo->prepare("UPDATE appointments SET status='cancelled' WHERE id=?")->execute([$appointmentId]);$pdo->prepare("UPDATE donation_pledges SET status='approved',updated_at=NOW() WHERE id=? AND status='scheduled'")->execute([$appt['pledge_id']]);$pdo->commit();flash('success','Appointment cancelled. The donor can choose another time.');}else flash('error','That appointment could not be changed.');redirect('charity/appointments.php');}
$stmt=$pdo->prepare("SELECT a.*,u.name donor_name,u.email,cr.title,cr.collection_location,COALESCE(SUM(di.quantity),0) quantity FROM appointments a JOIN donation_pledges dp ON dp.id=a.pledge_id JOIN users u ON u.id=dp.donor_id JOIN clothing_requests cr ON cr.id=dp.request_id LEFT JOIN donation_items di ON di.pledge_id=dp.id WHERE cr.charity_id=? GROUP BY a.id ORDER BY a.appointment_date DESC,a.time_slot DESC");$stmt->execute([$charityId]);$appointments=$stmt->fetchAll();$pageTitle='Drop-off appointments';require __DIR__ . '/../includes/header.php'; ?>
<section class="dashboard"><div class="shell"><div class="welcome-row"><div><span class="eyebrow">The handover moment</span><h1>Drop-off appointments</h1><p>Confirmed donations are counted only after you mark them received.</p></div><a class="button button-outline" href="<?=e(url('charity/donations.php'))?>">Manage donations</a></div><div class="panel"><?php if(!$appointments):?><div class="empty"><span class="empty-icon">◷</span>No drop-offs have been booked yet.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Date & time</th><th>Donor</th><th>Request</th><th>Items</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($appointments as $a):?><tr><td><strong><?=format_date($a['appointment_date'])?></strong><br><span class="muted"><?=e(substr($a['time_slot'],0,5))?></span></td><td><?=e($a['donor_name'])?><br><span class="muted"><?=e($a['email'])?></span></td><td><?=e($a['title'])?><br><span class="muted"><?=e($a['collection_location'])?></span></td><td><?=$a['quantity']?></td><td><span class="status <?=e(status_class($a['status']))?>"><?=e($a['status'])?></span></td><td><?php if($a['status']==='booked'):?><form method="post" data-loading data-confirm="Cancel this appointment? The donor can book another slot."><?=csrf_field()?><input type="hidden" name="appointment_id" value="<?=$a['id']?>"><button class="button button-danger button-small">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
